export async function discoverCustomProviderModels(provider: KeatingCustomProvider): Promise<Model<Api>[]> {
	if (AUTO_DISCOVERY_TYPES.has(provider.type)) {
		let models: Model<Api>[];
		switch (provider.type) {
			case "ollama":
				models = await discoverOllamaModels(provider.baseUrl);
				break;
			case "llama.cpp":
				models = await discoverLlamaCppModels(provider.baseUrl, provider.apiKey);
				break;
			case "vllm":
				models = await discoverVllmModels(provider.baseUrl, provider.apiKey);
				break;
			case "lmstudio":
				models = await discoverLmStudioModels(provider.baseUrl);
				break;
			default:
				models = [];
		}

		return models.map((model) => ({ ...model, provider: provider.name }));
	}

	if (OPENAI_COMPATIBLE_TYPES.has(provider.type)) {
		const discovered = await discoverOpenAiCompatibleModels(provider);
		return discovered.models;
	}

	return (provider.models || []).map((model) => ({
		...model,
		provider: provider.name,
		baseUrl: model.baseUrl || provider.baseUrl,
		api: model.api || manualProviderApi(provider.type),
	}));
}

export async function getCustomProviders(): Promise<KeatingCustomProvider[]> {
	return (await getAppStorage().customProviders.getAll()) as KeatingCustomProvider[];
}

export async function syncCustomProviderKeys(): Promise<void> {
	const storage = getAppStorage();
	const providers = await getCustomProviders();

	await Promise.all(
		providers.map(async (provider) => {
			if (provider.apiKey) {
				await storage.providerKeys.set(provider.name, provider.apiKey);
			}
		}),
	);
}

export async function getProviderApiKey(providerName: string): Promise<string | undefined> {
	const oauthId = providerToOAuthId(providerName);
	if (oauthId) {
		const token = await getOAuthAccessToken(oauthId);
		if (token) return token;
	}

	const storage = getAppStorage();
	const storedKey = await storage.providerKeys.get(providerName);
	if (storedKey) return storedKey;

	const customProviders = await getCustomProviders();
	return customProviders.find((provider) => provider.name === providerName)?.apiKey;
}

const FALLBACK_CHAT_MODEL_IDS: Record<string, string[]> = {
	[DIO_PROVIDER_ID]: [DIO_DEFAULT_MODEL.id],
	openai: ["gpt-5.5", "gpt-5.5-pro", "gpt-5.4", "gpt-5.3-chat-latest", "gpt-5.2", "gpt-5.1", "gpt-5"],
	anthropic: ["claude-sonnet-4-6", "claude-opus-4-8", "claude-opus-4-7", "claude-sonnet-4-5", "claude-haiku-4-5"],
	google: ["gemini-3.1-pro-preview", "gemini-3.5-flash", "gemini-3-pro-preview", "gemini-2.5-pro"],
};

function providerNeedsKey(provider: string): boolean {
	return provider !== "browser";
}

function preferredModelForProvider(models: Array<Model<Api>>, provider: string): Model<Api> | undefined {
	const providerModels = models.filter((model) => model.provider === provider);
	const ids = FALLBACK_CHAT_MODEL_IDS[provider] ?? [];
	for (const id of ids) {
		const found = providerModels.find((model) => model.id === id);
		if (found) return found;
	}
	return providerModels[0];
}

export async function resolveAvailableChatModel(current: Model<Api>): Promise<Model<Api>> {
	if (!providerNeedsKey(current.provider) || await getProviderApiKey(current.provider)) {
		return current;
	}

	const models = await getSelectableModels();
	for (const provider of [DIO_PROVIDER_ID, "openai", "anthropic", "google"]) {
		if (!(await getProviderApiKey(provider))) continue;
		const model = preferredModelForProvider(models, provider);
		if (model) return model;
	}

	return current;
}

